#pragma once#pragma warning (disable:4251) // class 'std::queue' needs to have dll-interface to be used by clients of struct 'IAdviseHostImpl<IAdviseSink>#include <assert.h>#include <vector>#include <queue>#include <algorithm>using std::vector;#include "./IAdviseHost.h"template < class IAdviseSink > class IAdviseHostLockerImpl;template < class IAdviseSink > class CAdviseHostSinkIterator;template < class IAdviseSink >struct IAdviseHostImpl : virtual public IAdviseHost<IAdviseSink>{    friend class IAdviseHostLockerImpl<IAdviseSink>;    friend class CAdviseHostSinkIterator<IAdviseSink>;    typedef IAdviseHostLockerImpl<IAdviseSink> lock_type;    typedef vector<IAdviseSink> CIAdviseSinkList;    typedef typename CIAdviseSinkList::iterator CIAdviseSinkListIter;    IAdviseHostImpl() : itsAdviseLocks( 0 ) {}    virtual const bool Advise  ( IAdviseSink pIAdviseSink );    virtual const bool Unadvise( IAdviseSink pIAdviseSink );    void ForEach()    {      lock_type lock(this);      for(CIAdviseSinkListIter iter(itsSinks.begin() ), end(itsSinks.end() ); iter != end; ++iter)      {        (*iter)();      }    }    template <typename A1>    void ForEach( const A1 & arg1)    {      lock_type lock(this);      for(CIAdviseSinkListIter iter(itsSinks.begin() ), end(itsSinks.end() ); iter != end; ++iter)      {        (*iter)(arg1);      }    }    template <typename A1>    void ForFirst( const A1 & arg1)    {      lock_type lock(this);      if( itsSinks.empty() )        return;      (*itsSinks.begin())(arg1);    }    template <typename A1, typename A2>    void Notify( A1 & arg1, A2 & arg2)    {      lock_type lock(this);	  CIAdviseSinkListIter iter = itsSinks.begin();	  if (iter != itsSinks.end())		  (*iter)(arg1, arg2);    }    template <typename A1, typename A2>    void ForEach( const A1 & arg1, const A2 & arg2)    {      lock_type lock(this);      for(CIAdviseSinkListIter iter(itsSinks.begin() ), end(itsSinks.end() ); iter != end; ++iter)      {        (*iter)(arg1, arg2);      }    }    template <typename A1, typename A2, typename A3>    void ForEach( const A1 & arg1, const A2 &arg2, const A3 & arg3)    {      lock_type lock(this);      for(CIAdviseSinkListIter iter(itsSinks.begin() ), end(itsSinks.end() ); iter != end; ++iter)      {        (*iter)(arg1, arg2, arg3);      }    }protected:    bool  IsAdviseLocked() const { assert ( 0 <= itsAdviseLocks ); return 0 < itsAdviseLocks; }    short LockAdvise()           { assert ( 0 <= itsAdviseLocks ); return short ( ++itsAdviseLocks ); }    short UnlockAdvise();    typedef const bool ( IAdviseHostImpl<IAdviseSink>::* tAdviseOperation ) ( IAdviseSink );    typedef std::queue < std::pair < tAdviseOperation, IAdviseSink > > tUpdateRequests;    tUpdateRequests                itsAdviseQueue;    size_t                         itsAdviseLocks;    CIAdviseSinkList itsSinks;};template < class IAdviseSink >short IAdviseHostImpl<IAdviseSink>::UnlockAdvise(){    assert ( 0 < itsAdviseLocks );    --itsAdviseLocks;    size_t fail_count = 0;    if ( ! IsAdviseLocked() )      for ( ; itsAdviseQueue.size(); itsAdviseQueue.pop() )      {        const tUpdateRequests::value_type & reqCurr = itsAdviseQueue.front();        if ( !( this ->* reqCurr.first ) ( reqCurr.second ) )          fail_count++;      }    //assert( fail_count == 0 );    return short ( itsAdviseLocks );}template < class IAdviseSink >const bool IAdviseHostImpl<IAdviseSink>::Advise( IAdviseSink pIAdviseSink ){    if( !pIAdviseSink || ( std::find( itsSinks.begin(), itsSinks.end(), pIAdviseSink ) != itsSinks.end()) )      return false;    typedef IAdviseHostImpl<IAdviseSink> mytype;    if ( IsAdviseLocked() )    {       itsAdviseQueue.push ( tUpdateRequests::value_type ( &mytype::Advise, pIAdviseSink ) );       return true;    }    itsSinks.push_back( pIAdviseSink );    return true;}template < class IAdviseSink >const bool IAdviseHostImpl<IAdviseSink>::Unadvise( IAdviseSink pIAdviseSink ){    if ( !pIAdviseSink )      return false;    if ( IsAdviseLocked() )    {       itsAdviseQueue.push ( tUpdateRequests::value_type ( &IAdviseHostImpl<IAdviseSink>::Unadvise, pIAdviseSink ) );       return true;    }    const std::vector<IAdviseSink>::iterator i = std::find( itsSinks.begin(), itsSinks.end(), pIAdviseSink );    if ( i != itsSinks.end() )    {      itsSinks.erase( i );      return true;    }    return false;}template < class IAdviseSink > class IAdviseHostLockerImpl{public:    typedef IAdviseHostImpl<IAdviseSink> value_type;    IAdviseHostLockerImpl(value_type* pOwner) : m_pOwner(pOwner)    {        if(m_pOwner)        {            m_pOwner->LockAdvise();        }    }    ~IAdviseHostLockerImpl()    {        if(m_pOwner)        {            m_pOwner->UnlockAdvise();        }    }private:    value_type* m_pOwner;};template< class IAdviseSink > class CAdviseHostSinkIterator{public:    typedef IAdviseHostImpl<IAdviseSink> host_type;    typedef typename host_type::sink_type value_type;    CAdviseHostSinkIterator(host_type* pHost) : m_pHost(pHost), m_lock(pHost), m_pos(0)    {    }    void Reset()    {        m_pos = 0;    }    IAdviseSink* Next()    {        return (m_pos < m_pHost->itsSinks.size()) ? m_pHost->itsSinks[m_pos++] : NULL;    }private:    host_type*                         m_pHost;    IAdviseHostLockerImpl<IAdviseSink> m_lock;    size_t                             m_pos;};